//! #227: bubble/dew points beyond the dry A13 set against independent native
//! Clapeyron references (`validation/fixtures/a13-extended-v1.json`, generated by
//! `validation/julia/generate_a13_extended.jl` from
//! `validation/a13-extended-inputs.json`), plus explicit near-critical, freezing
//! and non-convergence failures.
#[path = "../../thermo-solvers/tests/common/mod.rs"]
mod common;

use property_packages::cubic_model_with_pseudo_components;
use serde_json::Value;
use thermo_data::{ComponentDatabase, PseudoComponentInput};
use thermo_models::{CubicModel, CubicVariant};
use thermo_solvers::{
    CubicSaturationKind as Kind, EnvelopeStop, SaturationOptions, SaturationPoint,
    saturation_pressure, saturation_temperature, trace_phase_envelope,
};
use thermo_types::{
    CalculationError, ComponentId, Composition, CompositionBasis, NormalizationPolicy, Pressure,
    Temperature,
};

const FIXTURE: &str = "a13-extended-v1.json";

fn values(v: &Value) -> Vec<f64> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_f64().unwrap())
        .collect()
}

fn inputs() -> Value {
    serde_json::from_str(include_str!("../../../validation/a13-extended-inputs.json")).unwrap()
}

fn reference() -> Value {
    let text = std::env::var_os("THERMO_A13_EXTENDED_REFERENCE")
        .map(|p| std::fs::read_to_string(p).unwrap())
        .unwrap_or_else(|| {
            include_str!("../../../validation/fixtures/a13-extended-v1.json").into()
        });
    let f: Value = serde_json::from_str(&text).unwrap();
    assert_eq!(f["schema"], "a13-extended-clapeyron-v1");
    assert_eq!(f["julia_version"], "1.11.7");
    assert_eq!(f["clapeyron_version"], "0.6.30");
    common::assert_input_hashes(FIXTURE, &f);
    f
}

fn variant(c: &Value) -> CubicVariant {
    match c["variant"].as_str().unwrap() {
        "PR" => CubicVariant::PengRobinson,
        "PR-BM" => CubicVariant::PengRobinsonBostonMathias,
        other => panic!("{}: unknown variant {other}", c["id"]),
    }
}

/// Pseudo-components characterised from the Tb and SG of the independent
/// characterisation fixture, whose correlated constants the references use.
fn pseudo_inputs() -> Vec<PseudoComponentInput> {
    let fixture: Value = serde_json::from_str(include_str!(
        "../../../validation/fixtures/pseudo-components-v1.json"
    ))
    .unwrap();
    fixture["species"]
        .as_array()
        .unwrap()
        .iter()
        .map(|s| {
            PseudoComponentInput::new(
                s["id"].as_str().unwrap(),
                s["normal_boiling_point_K"].as_f64().unwrap(),
                s["specific_gravity_60F"].as_f64().unwrap(),
            )
        })
        .collect()
}

fn model(c: &Value) -> CubicModel {
    let ids: Vec<String> = c["ids"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap().to_string())
        .collect();
    let z = values(&c["z"]);
    let kij: Vec<Vec<f64>> = c["kij"].as_array().unwrap().iter().map(values).collect();
    let source = "explicit #227 fixture interactions";
    if c["pseudo"].as_bool().unwrap_or(false) {
        let pseudo: Vec<_> = pseudo_inputs()
            .into_iter()
            .filter(|p| ids.contains(&p.id))
            .collect();
        return cubic_model_with_pseudo_components(variant(c), &ids, &pseudo, kij, source)
            .unwrap()
            .with_fractions(&z)
            .unwrap();
    }
    let composition = Composition::new(
        CompositionBasis::Mole,
        ids.iter()
            .zip(z)
            .map(|(id, x)| (ComponentId::new(id.clone()).unwrap(), x))
            .collect(),
        NormalizationPolicy::RequireUnitSum,
    )
    .unwrap();
    CubicModel::new(
        &ComponentDatabase::embedded().unwrap(),
        &composition,
        variant(c),
        kij,
        source,
    )
    .unwrap()
}

fn bounds(c: &Value) -> SaturationOptions {
    let t = values(&c["bounds"]["T"]);
    let p = values(&c["bounds"]["p"]);
    SaturationOptions {
        minimum_temperature_k: t[0],
        maximum_temperature_k: t[1],
        minimum_pressure_pa: p[0],
        maximum_pressure_pa: p[1],
        ..Default::default()
    }
}

fn kind(c: &Value) -> Kind {
    if c["kind"] == "bubble" {
        Kind::Bubble
    } else {
        Kind::Dew
    }
}

fn solve(c: &Value, o: SaturationOptions) -> Result<SaturationPoint, CalculationError> {
    let m = model(c);
    let fixed = c["fixed"].as_f64().unwrap();
    if c["unknown"] == "pressure" {
        saturation_pressure(&m, Temperature::new(fixed).unwrap(), kind(c), o)
    } else {
        saturation_temperature(&m, Pressure::new(fixed).unwrap(), kind(c), o)
    }
}

fn close(f: &Value, key: &str, actual: f64, expected: f64, id: &str) {
    let limits = values(&f["tolerances"][key]);
    assert!(
        actual.is_finite() && (actual - expected).abs() <= limits[0] + limits[1] * expected.abs(),
        "{id} {key}: Rust={actual:e} Clapeyron={expected:e}"
    );
}

fn close_all(f: &Value, key: &str, actual: &[f64], expected: &Value, id: &str) {
    let expected = values(expected);
    assert_eq!(actual.len(), expected.len(), "{id} {key}: component count");
    for (a, b) in actual.iter().zip(expected) {
        close(f, key, *a, b, id);
    }
}

#[test]
fn extended_boundaries_match_independent_clapeyron_references() {
    let f = reference();
    let input = inputs();
    let cases = input["cases"].as_array().unwrap();
    let references = f["cases"].as_array().unwrap();
    assert_eq!(cases.len(), references.len());
    assert!(cases.len() >= 60);
    let mut three_phase = 0;
    for (c, r) in cases.iter().zip(references) {
        assert_eq!(c["id"], r["id"]);
        let id = c["id"].as_str().unwrap();
        let point = solve(c, bounds(c)).unwrap_or_else(|e| panic!("{id}: {e}"));
        close(
            &f,
            "temperature",
            point.temperature_k,
            r["T"].as_f64().unwrap(),
            id,
        );
        close(
            &f,
            "pressure",
            point.pressure_pa,
            r["p"].as_f64().unwrap(),
            id,
        );
        close_all(&f, "composition", &point.liquid_composition, &r["x"], id);
        close_all(&f, "composition", &point.vapor_composition, &r["y"], id);
        close(
            &f,
            "volume",
            point.liquid.molar_volume,
            r["vl"].as_f64().unwrap(),
            id,
        );
        close(
            &f,
            "volume",
            point.vapor.molar_volume,
            r["vv"].as_f64().unwrap(),
            id,
        );
        assert!(point.max_ln_fugacity_residual < 1e-9, "{id}");
        let active = values(&c["z"]).iter().filter(|z| **z > 0.0).count();
        if c["three_phase"].as_bool().unwrap_or(false) {
            three_phase += 1;
            let second = point
                .second_liquid
                .as_ref()
                .unwrap_or_else(|| panic!("{id}: no second liquid"));
            close_all(&f, "x2", &second.composition, &r["x2"], id);
            close(
                &f,
                "vl2",
                second.state.molar_volume,
                r["vl2"].as_f64().unwrap(),
                id,
            );
            close(
                &f,
                "beta",
                second.material_fraction,
                r["beta"].as_f64().unwrap(),
                id,
            );
            assert!(
                second.state.mass_density >= point.liquid.mass_density,
                "{id}"
            );
            assert_eq!(point.multiphase_stability.len(), 1, "{id}");
        } else {
            assert!(point.second_liquid.is_none(), "{id}");
            // Mixtures outside the dry set carry multiphase (VLLE) evidence.
            let expected = if active > 1 { 2 } else { 0 };
            assert_eq!(point.multiphase_stability.len(), expected, "{id}");
        }
        assert!(
            point
                .multiphase_stability
                .iter()
                .all(|s| s.stable_in_trials)
        );
        println!(
            "PASS {id}: T={} p={}",
            point.temperature_k, point.pressure_pa
        );
    }
    assert!(three_phase >= 4);
}

#[test]
fn sampled_envelopes_match_independent_points() {
    let f = reference();
    let input = inputs();
    let all = input["cases"].as_array().unwrap();
    for (group, lo, hi, step) in [
        ("water-bubble", 300.0, 575.0, 25.0),
        ("mw-bubble", 320.0, 460.0, 20.0),
    ] {
        let cases: Vec<_> = all.iter().filter(|c| c["trace_group"] == group).collect();
        let o = SaturationOptions {
            minimum_temperature_k: lo,
            maximum_temperature_k: hi,
            ..bounds(cases[0])
        };
        let trace = trace_phase_envelope(&model(cases[0]), Kind::Bubble, step, 100, o).unwrap();
        assert!(
            matches!(trace.stop, EnvelopeStop::RequestedRangeComplete),
            "{group}: {:?}",
            trace.stop
        );
        assert_eq!(trace.points.len(), cases.len(), "{group}");
        for (point, c) in trace.points.iter().zip(cases) {
            let r = f["cases"]
                .as_array()
                .unwrap()
                .iter()
                .find(|r| r["id"] == c["id"])
                .unwrap();
            close(
                &f,
                "temperature",
                point.temperature_k,
                r["T"].as_f64().unwrap(),
                group,
            );
            close(
                &f,
                "pressure",
                point.pressure_pa,
                r["p"].as_f64().unwrap(),
                group,
            );
        }
    }
}

fn case(id: &str) -> Value {
    inputs()["cases"]
        .as_array()
        .unwrap()
        .iter()
        .find(|c| c["id"] == id)
        .unwrap_or_else(|| panic!("no case {id}"))
        .clone()
}

fn wide() -> SaturationOptions {
    SaturationOptions {
        minimum_temperature_k: 200.0,
        maximum_temperature_k: 600.0,
        minimum_pressure_pa: 1e3,
        maximum_pressure_pa: 1e8,
        ..Default::default()
    }
}

/// Near-critical states fail explicitly: pure fluids above 0.95 Tc, and traces
/// stop with a near-critical diagnostic instead of returning unverified points.
#[test]
fn near_critical_states_fail_explicitly() {
    // Water's 0.95 Tc (614.7 K) lies above the 600 K cubic interval, so its
    // whole saturation curve inside the interval is supported (see the
    // references); methanol, ethane and 1-butanol reach 0.95 Tc inside it.
    let methanol = model(&case("methanol-bubble-pressure-300K-PR"));
    let ethane = model(&case("ethane-dew-temperature-1e+06Pa-PR"));
    let butanol = model(&case("butanol-bubble-pressure-400K-PR"));
    for (m, t) in [(&methanol, 495.0), (&ethane, 295.0), (&butanol, 540.0)] {
        let r = saturation_pressure(m, Temperature::new(t).unwrap(), Kind::Bubble, wide());
        assert!(
            matches!(r, Err(CalculationError::OutsideValidityDomain(ref e)) if e.contains("near-critical")),
            "{t}: {r:?}"
        );
    }
    // A pressure above the vapor pressure at 0.95 Tc has no supported saturation temperature.
    let r = saturation_temperature(&ethane, Pressure::new(4.5e6).unwrap(), Kind::Dew, wide());
    assert!(
        matches!(r, Err(CalculationError::OutsideValidityDomain(ref e)) if e.contains("near-critical")),
        "{r:?}"
    );
    let trace = trace_phase_envelope(
        &methanol,
        Kind::Bubble,
        5.0,
        100,
        SaturationOptions {
            minimum_temperature_k: 470.0,
            ..wide()
        },
    )
    .unwrap();
    assert!(
        matches!(
            trace.stop,
            EnvelopeStop::NearCritical {
                temperature_k: 490.0,
                ..
            }
        ),
        "{:?}",
        trace.stop
    );
    assert_eq!(trace.supported_temperature_range_k, Some([470.0, 485.0]));
    // Methanol/water and ethane/propane bubble envelopes approach their mixture
    // critical points inside 600 K; the trace keeps only verified points.
    let mw = model(&case("mw-bubble-pressure-320K-PR"));
    let ethane_propane = {
        let mut c = case("mw-bubble-pressure-320K-PR");
        c["ids"] = serde_json::json!(["ethane", "propane"]);
        c["kij"] = serde_json::json!([[0.0, 0.0], [0.0, 0.0]]);
        model(&c)
    };
    // The methanol/water bubble search stops without a verified point at 550 K
    // (9.9 MPa in the reference model): an explicit unverified-boundary stop,
    // not an extrapolated value.
    let trace = trace_phase_envelope(
        &mw,
        Kind::Bubble,
        5.0,
        100,
        SaturationOptions {
            minimum_temperature_k: 450.0,
            ..wide()
        },
    )
    .unwrap();
    assert!(
        !matches!(trace.stop, EnvelopeStop::RequestedRangeComplete),
        "{:?}",
        trace.stop
    );
    println!("methanol/water bubble trace stop: {:?}", trace.stop);
    {
        let (m, lo) = (&ethane_propane, 300.0);
        let trace = trace_phase_envelope(
            m,
            Kind::Bubble,
            5.0,
            100,
            SaturationOptions {
                minimum_temperature_k: lo,
                ..wide()
            },
        )
        .unwrap();
        assert!(
            matches!(trace.stop, EnvelopeStop::NearCritical { .. }),
            "{lo}: {:?}",
            trace.stop
        );
        assert!(!trace.points.is_empty());
        for p in &trace.points {
            assert!(p.max_ln_fugacity_residual < 1e-9);
            assert!(p.vapor.molar_volume / p.liquid.molar_volume >= 1.5);
        }
    }
}

/// Solids are not modelled: boundaries below the water or CO2 triple point with
/// an essentially pure liquid of that component are outside the domain.
#[test]
fn freezing_boundaries_are_outside_the_domain() {
    let water = model(&case("water-bubble-pressure-300K-PR"));
    let co2 = model(&case("co2-bubble-pressure-220K-PR-BM"));
    let low = SaturationOptions {
        minimum_pressure_pa: 1.0,
        ..wide()
    };
    for (m, t) in [(&water, 260.0), (&co2, 210.0)] {
        let r = saturation_pressure(m, Temperature::new(t).unwrap(), Kind::Bubble, low);
        assert!(
            matches!(r, Err(CalculationError::OutsideValidityDomain(ref e)) if e.contains("triple point")),
            "{t}: {r:?}"
        );
    }
    // A trace-water gas whose water dew point lies below 273.16 K.
    let mut c = case("wet-gas-trace-water-dew-temperature-2e+06Pa-PR");
    c["ids"] = serde_json::json!(["methane", "water"]);
    c["z"] = serde_json::json!([0.9999, 0.0001]);
    c["kij"] = serde_json::json!([[0.0, 0.5], [0.5, 0.0]]);
    let r = saturation_temperature(&model(&c), Pressure::new(1e6).unwrap(), Kind::Dew, low);
    assert!(
        matches!(r, Err(CalculationError::OutsideValidityDomain(ref e)) if e.contains("triple point")),
        "{r:?}"
    );
}

/// Iteration limits and unsupported branches stay explicit for the extended set.
#[test]
fn nonconvergent_cases_fail_explicitly() {
    let limited = |c: &Value| SaturationOptions {
        max_iterations: 1,
        ..bounds(c)
    };
    for id in [
        "wet-gas-aqueous-dew-temperature-2e+06Pa-PR",
        "mw-bubble-temperature-101325Pa-PR",
        "propane-water-3phase-bubble-pressure-320K-PR",
    ] {
        let c = case(id);
        let r = solve(&c, limited(&c));
        assert!(
            matches!(r, Err(CalculationError::NonConvergence(_))),
            "{id}: {:?}",
            r.map(|p| p.temperature_k)
        );
    }
    // A specified liquid that splits (PR with kij = 0 predicts a methanol/water
    // liquid split near 320 K) never yields a two-phase bubble point.
    let mut c = case("mw-bubble-pressure-320K-PR");
    c["kij"] = serde_json::json!([[0.0, 0.0], [0.0, 0.0]]);
    if let Ok(point) = solve(&c, bounds(&c)) {
        assert!(point.second_liquid.is_some());
    }
}
